	private static void simpleBlockWithRenderType(Block block, String renderType) {
		simpleBlock(block, TechnologicaModels.cubeAll(name(block), blockTexture(block)).renderType(renderType));
	}

	private static void slabBlockWithRenderType(SlabBlock block, ResourceLocation doubleslab, ResourceLocation side, ResourceLocation bottom, ResourceLocation top, String renderType) {
		getVariantBuilder(block).partialState().with(SlabBlock.TYPE, SlabType.BOTTOM).addModels(new TLReGenConfiguredModel(TechnologicaModels.slab(block, side, bottom, top, "solid").renderType(renderType))).partialState().with(SlabBlock.TYPE, SlabType.TOP).addModels(new TLReGenConfiguredModel(TechnologicaModels.slabTop(block, side, bottom, top, "solid").renderType(renderType))).partialState().with(SlabBlock.TYPE, SlabType.DOUBLE).addModels(new TLReGenConfiguredModel(TechnologicaModels.getExistingFile(doubleslab)));
	}

	private static void buttonBlockWithRenderType(ButtonBlock block, ResourceLocation texture, String renderType) {
		ModelFile button = TechnologicaModels.button(name(block), texture).renderType(renderType);
		ModelFile buttonPressed = TechnologicaModels.buttonPressed(name(block) + "_pressed", texture).renderType(renderType);
		getVariantBuilder(block).forAllStates(state -> {
			Direction facing = state.getValue(ButtonBlock.FACING);
			AttachFace face = state.getValue(ButtonBlock.FACE);
			boolean powered = state.getValue(ButtonBlock.POWERED);
			return TLReGenConfiguredModel.builder().modelFile(powered ? buttonPressed : button).rotationX(face == AttachFace.FLOOR ? 0 : (face == AttachFace.WALL ? 90 : 180)).rotationY((int) (face == AttachFace.CEILING ? facing : facing.getOpposite()).toYRot()).uvLock(face == AttachFace.WALL).build();
		});
	}

