	private static void stairsBlockWithRenderType(StairBlock block, ResourceLocation side, ResourceLocation bottom, ResourceLocation top, String renderType) {
		stairsBlockInternalWithRenderType(block, ForgeRegistries.BLOCKS.getKey(block).toString(), side, bottom, top, renderType);
	}

	private static void stairsBlockInternalWithRenderType(StairBlock block, String baseName, ResourceLocation side, ResourceLocation bottom, ResourceLocation top, String renderType) {
		ModelFile stairs = TechnologicaModels.stairs(baseName, side, bottom, top).renderType(renderType);
		ModelFile stairsInner = TechnologicaModels.stairsInner(block, side, bottom, top, renderType);
		ModelFile stairsOuter = TechnologicaModels.stairsOuter(block, side, bottom, top, renderType);
		stairsBlock(block, stairs, stairsInner, stairsOuter);
	}

	private static void stairsBlock(StairBlock block, ModelFile stairs, ModelFile stairsInner, ModelFile stairsOuter) {
		getVariantBuilder(block).forAllStatesExcept(state -> {
			Direction facing = state.getValue(StairBlock.FACING);
			Half half = state.getValue(StairBlock.HALF);
			StairsShape shape = state.getValue(StairBlock.SHAPE);
			int yRot = (int) facing.getClockWise().toYRot(); // Stairs model is rotated 90 degrees clockwise for some reason
			if (shape == StairsShape.INNER_LEFT || shape == StairsShape.OUTER_LEFT) {
				yRot += 270; // Left facing stairs are rotated 90 degrees clockwise
			}
			if (shape != StairsShape.STRAIGHT && half == Half.TOP) {
				yRot += 90; // Top stairs are rotated 90 degrees clockwise
			}
			yRot %= 360;
			boolean uvlock = yRot != 0 || half == Half.TOP; // Don't set uvlock for states that have no rotation
			return TLReGenConfiguredModel.builder().modelFile(shape == StairsShape.STRAIGHT ? stairs : shape == StairsShape.INNER_LEFT || shape == StairsShape.INNER_RIGHT ? stairsInner : stairsOuter).rotationX(half == Half.BOTTOM ? 0 : 180).rotationY(yRot).uvLock(uvlock).build();
		}, StairBlock.WATERLOGGED);
	}

	private static void fenceBlockWithRenderType(FenceBlock block, ResourceLocation texture, String renderType) {
		String baseName = ForgeRegistries.BLOCKS.getKey(block).toString();
		fourWayBlock(block, TechnologicaModels.fencePost(baseName + "_post", texture).renderType(renderType), TechnologicaModels.fenceSide(baseName + "_side", texture).renderType(renderType));
	}

	private static void fourWayBlock(CrossCollisionBlock block, ModelFile post, ModelFile side) {
		MultiPartBlockStateBuilder builder = getMultipartBuilder(block).part().modelFile(post).addModel().end();
		fourWayMultipart(builder, side);
	}

	private static void fourWayMultipart(MultiPartBlockStateBuilder builder, ModelFile side) {
		PipeBlock.PROPERTY_BY_DIRECTION.entrySet().forEach(e -> {
			Direction dir = e.getKey();
			if (dir.getAxis().isHorizontal()) {
				builder.part().modelFile(side).rotationY((((int) dir.toYRot()) + 180) % 360).uvLock(true).addModel().condition(e.getValue(), true);
			}
		});
	}

